import collections
cand=[18,23,26,35,42,62,64,68,80,98,102,149]
cs=set(cand)
# candidate-involving closures across whole log per window, and check triangle lag distribution for candidates everywhere
def closures(lo,hi,delta=800,restrict=None):
    nb=collections.defaultdict(dict); res=[]
    for u,v,t in events:
        if lo<=t<=hi:
            su=nb[u]; sv=nb[v]
            for w in set(su)&set(sv)-{u,v}:
                m=max(su[w][-1],sv[w][-1])
                if t-m<=delta:
                    if restrict is None or (u in restrict or v in restrict or w in restrict):
                        res.append((u,v,t,w,t-m))
        nb[u].setdefault(v,[]).append(t)
        nb[v].setdefault(u,[]).append(t)
    return res
for lo in range(0,88001,4000):
    print(lo, len(closures(lo,lo+12000,800,cs)))
print("target",len(closures(22553,34553,800,cs)))
# also all triangles involving candidates regardless of lag in window
def alltri(lo,hi,restrict):
    nb=collections.defaultdict(dict); res=[]
    for u,v,t in events:
        if lo<=t<=hi:
            su=nb[u]; sv=nb[v]
            for w in set(su)&set(sv)-{u,v}:
                m=max(su[w][-1],sv[w][-1])
                if u in restrict or v in restrict or w in restrict: res.append(t-m)
        nb[u].setdefault(v,[]).append(t); nb[v].setdefault(u,[]).append(t)
    return res
